def to_subject_positions(apps, schema_editor):
    """Freezes of the first version were written in Lesson.lesson_number,
    which for shared course plans is a course-wide number (IT lesson 29 can
    be row 85). Re-express each as positions in its subject's own sequence:
    the lessons it covered → their rank among the plan rows of their subject
    → whole months of the frozen size from position 1. A freeze whose lessons
    cannot be placed protected nothing and is removed."""
    Freeze = apps.get_model("academic_progress", "NumberingFreeze")
    Lesson = apps.get_model("academy", "Lesson")
    GroupTeacher = apps.get_model("academy", "GroupTeacher")
    CourseLessonPlan = apps.get_model("academy", "CourseLessonPlan")
    GroupTeacherLessonPlan = apps.get_model("academy", "GroupTeacherLessonPlan")

    for freeze in list(Freeze.objects.filter(group__isnull=True)):
        gt = GroupTeacher.objects.filter(pk=freeze.group_teacher_id).select_related("group").first()
        if gt is None:
            freeze.delete()
            continue
        course_rows = list(CourseLessonPlan.objects.filter(course_id=gt.group.course_id)
                           .values_list("pk", "subject_id", "lesson_number"))
        course_rank, course_by_number = {}, {}
        for subject_id in {row[1] for row in course_rows}:
            ordered = sorted((n, pk) for pk, s, n in course_rows if s == subject_id)
            for position, (number, pk) in enumerate(ordered, start=1):
                course_rank[pk] = (subject_id, position)
                course_by_number[(subject_id, number)] = position
        own = sorted(GroupTeacherLessonPlan.objects.filter(group_teacher_id=gt.pk).values_list("lesson_number", "pk"))
        own_rank = {pk: i for i, (_, pk) in enumerate(own, start=1)}
        own_by_number = {n: i for i, (n, _) in enumerate(own, start=1)}

        highest: dict = {}
        lessons = Lesson.objects.filter(group_teacher_id=gt.pk, lesson_number__gte=freeze.first_lesson,
                                        lesson_number__lte=freeze.last_lesson).exclude(status="cancelled")
        for lesson in lessons:
            subject = lesson.subject_id or gt.subject_id
            place = None
            if lesson.individual_plan_id in own_rank:
                place = (subject, own_rank[lesson.individual_plan_id])
            elif lesson.plan_id in course_rank:
                place = course_rank[lesson.plan_id]
            elif own_by_number.get(lesson.lesson_number):
                place = (subject, own_by_number[lesson.lesson_number])
            elif (subject, lesson.lesson_number) in course_by_number:
                place = (subject, course_by_number[(subject, lesson.lesson_number)])
            if place is not None:
                highest[place[0]] = max(highest.get(place[0], 0), place[1])
        size = freeze.lessons_per_month
        for subject_id, last in highest.items():
            months = (last + size - 1) // size
            if not Freeze.objects.filter(group_id=gt.group_id, subject_id=subject_id, first_lesson=1).exists():
                Freeze.objects.create(group_id=gt.group_id, subject_id=subject_id, group_teacher_id=gt.pk, first_lesson=1,
                                      last_lesson=months * size, first_month=1, lessons_per_month=size,
                                      reason=freeze.reason, created_by_id=freeze.created_by_id)
        freeze.delete()


